import pandas as pd

def clean(df):
    df = df.copy()

    if 'sex' in df.columns:
        df['sex'] = df['sex'].apply(
            lambda x: x.strip().lower() if isinstance(x, str) else x
        )

    if 'flipper_length_mm' in df.columns:
        s = pd.to_numeric(df['flipper_length_mm'], errors='coerce')
        df['flipper_length_mm'] = s.abs()

    if 'body_mass_g' in df.columns:
        s = pd.to_numeric(df['body_mass_g'], errors='coerce')

        def fix_mass(x):
            if pd.isna(x):
                return x
            while x > 6500:
                x = x / 1000.0
            return x

        df['body_mass_g'] = s.apply(fix_mass)

    return df

def answer(df):
    d = clean(df)
    d = d.dropna(subset=['species', 'body_mass_g'])
    result = d.groupby('species')['body_mass_g'].mean()
    return {str(k): float(v) for k, v in result.items()}
